input_rows = []
for i in range(1, output_marker):  # Skip line 0 which is "Demo pair 1 input..."
    if lines[i].strip() and 'Demo' not in lines[i]:
        row = [int(x) for x in lines[i].split()]
        input_rows.append(row)
print(f"\nInput shape: {len(input_rows)}x{len(input_rows[0])}")
print(f"Input:")
for r in input_rows:
    print(r)

# Parse output (lines after output marker, skipping the header)
output_rows = []
for i in range(output_marker + 1, len(lines)):
    if lines[i].strip() and 'Demo' not in lines[i]:
        row = [int(x) for x in lines[i].split()]
        output_rows.append(row)
print(f"\nOutput shape: {len(output_rows)}x{len(output_rows[0])}")
print(f"Output:")
for r in output_rows:
    print(r)

# Find all differences
print("\n=== Diffs ===")
differences = []
for r in range(len(input_rows)):
    if r < len(output_rows):
        for c in range(len(input_rows[r])):
            if c < len(output_rows[r]):
                if input_rows[r][c] != output_rows[r][c]:
                    differences.append((r, c, input_rows[r][c], output_rows[r][c]))
            print(f"Input[{r}][{c}]={input_rows[r][c]} -> Output[{r}][{c}]={output_rows[r][c]}")
    else:
        # Input has more rows
        for c in range(len(input_rows[r])):
            print(f"Input[{r}][{c}]={input_rows[r][c]} -> Output[{r}][{c}]=(EOF)")

